81	        var subB1 = new Subcategory { Id = "SB1", Name = "Unterkategorie B1", CategoryId = "CB" };
82	
83	        _context.Categories.AddRange(categoryA, categoryB);
84	        _context.Subcategories.AddRange(subA1, subA2, subB1);
85	
86	        _context.Products.Add(new Product { Id = "PA1", Name = "Produkt A1", Description = "Beschreibung", SubcategoryId = "SA1" });
87	        _context.Products.Add(new Product { Id = "PA2", Name = "Produkt A2", Description = "Beschreibung", SubcategoryId = "SA2" });
88	        _context.Products.Add(new Product { Id = "PB1", Name = "Produkt B1", Description = "Beschreibung", SubcategoryId = "SB1" });
89	
90	        _context.SaveChanges();
