151	    ```html
152	    <nav>
153	      <button type="button" (click)="selectionCleared.emit()">Alle Kategorien</button>
154	      <ul>
155	        @for (category of categories(); track category.id) {
156	          <li>
157	            <button type="button" (click)="categorySelected.emit(category.id)">{{ category.name }}</button>
158	            <ul>
159	              @for (subcategory of category.subcategories; track subcategory.id) {
160	                <li>
161	                  <button type="button" (click)="subcategorySelected.emit(subcategory.id)">{{ subcategory.name }}</button>
162	                </li>
163	              }
164	            </ul>
165	          </li>
166	        }
167	      </ul>
