     7	public class CatalogService(AppDbContext context)
     8	{
     9	    public const int PageSize = 20;
    10	
    11	    public async Task<PagedResult<Product>> GetProductsAsync(int page, string? categoryId = null, string? subcategoryId = null, CancellationToken ct = default)
