    10	  templateUrl: './product-list.html'
    11	})
    12	export class ProductList {
    13	  private catalogApi = inject(CatalogApiService);
    14	
    15	  protected readonly page = signal(1);
    16	  protected readonly items = signal<ProductSummary[]>([]);
    17	  protected readonly totalCount = signal(0);
    18	  protected readonly loading = signal(false);
    19	  protected readonly pageSize = signal(0);
    20	  protected readonly categories = signal<CategorySummary[]>([]);
    21	  protected readonly selectedCategoryId = signal<string | null>(null);
    22	  protected readonly selectedSubcategoryId = signal<string | null>(null);
    23	
    24	  protected readonly totalPages = computed(() => Math.max(1, Math.ceil(this.totalCount() / (this.pageSize() || 1))));
    25	  protected readonly hasPreviousPage = computed(() => this.page() > 1);
    26	  protected readonly hasNextPage = computed(() => this.page() * this.pageSize() < this.totalCount());
    27	
    28	  constructor() {
    29	    this.loadPage(this.page());
    30	    this.loadCategories();
    31	  }
    32	
    33	  protected goToPreviousPage(): void {
    34	    if (this.hasPreviousPage() && !this.loading()) {
    35	      this.loadPage(this.page() - 1);
    36	    }
    37	  }
    38	
    39	  protected goToNextPage(): void {
    40	    if (this.hasNextPage() && !this.loading()) {
    41	      this.loadPage(this.page() + 1);
    42	    }
    43	  }
    44	
    45	  protected selectCategory(categoryId: string): void {
    46	    if (this.loading()) {
    47	      return;
    48	    }
    49	    this.selectedCategoryId.set(categoryId);
    50	    this.selectedSubcategoryId.set(null);
    51	    this.loadPage(1);
    52	  }
    53	
    54	  protected selectSubcategory(subcategoryId: string): void {
    55	    if (this.loading()) {
    56	      return;
    57	    }
    58	    this.selectedCategoryId.set(null);
    59	    this.selectedSubcategoryId.set(subcategoryId);
    60	    this.loadPage(1);
    61	  }
    62	
    63	  protected clearSelection(): void {
    64	    if (this.loading()) {
    65	      return;
    66	    }
    67	    this.selectedCategoryId.set(null);
    68	    this.selectedSubcategoryId.set(null);
    69	    this.loadPage(1);
    70	  }
    71	
    72	  private loadCategories(): void {
    73	    this.catalogApi.getCategories().subscribe({
    74	      next: (categories) => {
    75	        this.categories.set(categories);
    76	      },
    77	      error: () => {
    78	        this.categories.set([]);
    79	      }
    80	    });
    81	  }
    82	
    83	  private loadPage(page: number): void {
    84	    this.loading.set(true);
    85	    this.catalogApi.getProducts(page, this.selectedCategoryId(), this.selectedSubcategoryId()).subscribe({
    86	      next: (response) => {
    87	        this.page.set(response.page);
    88	        this.items.set(response.items);
    89	        this.totalCount.set(response.totalCount);
    90	        this.pageSize.set(response.pageSize);
    91	        this.loading.set(false);
    92	      },
    93	      error: () => {
    94	        this.loading.set(false);
    95	      }
    96	    });
    97	  }
    98	}
